<script setup>
import {ref} from 'vue';import {Head,usePage,router} from '@inertiajs/vue3';import AppLayout from '../../layouts/AppLayout.vue';import HubNav from './HubNav.vue';import './hub.css';
defineProps({total:Number,imports:Array});const page=usePage();const file=ref(null),preview=ref(null),result=ref(null),busy=ref(false),error=ref('');
const labels={source_contacts:'Контактов в файле',source_companies:'Компаний в справочнике',existing:'Уже в базе',to_add:'Будет добавлено',new_companies:'Новых компаний',unchanged:'Уже существуют',review:'Совпадения — пропущены для ручной проверки',reachable:'С каналом связи в файле',possible_duplicates:'Возможные дубли в файле',total_after:'Контактов после импорта'};
function select(e){file.value=e.target.files[0]||null;preview.value=null;result.value=null;error.value='';}
async function run(action){busy.value=true;error.value='';try{const body=new FormData();body.append('workbook',file.value);const r=await fetch('/projects/sales-hub/import/'+action,{method:'POST',body,credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':page.props.csrfToken}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Ошибка загрузки: '+r.status);if(action==='preview')preview.value=d;else{result.value=d;preview.value=null;router.reload({only:['total','imports']});}}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><Head title="Sales Hub — импорт"/><AppLayout><div class="saleshub"><HubNav/><p class="eyebrow">DATA / IMPORT</p><h1>Импорт Excel</h1><p>Сейчас в базе: <strong>{{total}}</strong> контактов. Загрузите исходную Google Таблицу в формате XLSX. Файл не сохраняется в репозитории.</p><section class="panel"><h2>1. Предварительная проверка</h2><input type="file" accept=".xlsx" @change="select" :disabled="busy"><button class="primary" :disabled="!file||busy" @click="run('preview')">{{busy?'Обработка…':'Проверить файл'}}</button><p class="muted">При первом импорте все исходные контакты сохраняются, включая возможные дубли. При повторном импорте существующие контакты и совпадения по имени/компании или каналам не перезаписываются. Совпадения требуют ручной проверки в исходном файле.</p><p v-if="error" class="error" role="alert">{{error}}</p></section><section v-if="preview||result" class="panel"><h2>{{result?'Импорт завершён':'2. Подтверждение'}}</h2><div v-for="(n,k) in (result||preview)" :key="k" class="analytics-row"><span>{{labels[k]||k}}</span><strong>{{n}}</strong></div><button v-if="preview" class="primary" :disabled="busy" @click="run('commit')">Подтвердить импорт</button></section><section class="panel"><h2>История загрузок</h2><div v-for="i in imports" :key="i.id" class="analytics-row"><span>{{i.created_at}}</span><strong>{{i.contacts}} контактов / {{i.companies}} компаний</strong></div><p v-if="!imports.length">Пока нет загрузок.</p></section></div></AppLayout></template>